    graph={'@context':'https://schema.org','@graph':[{'@type':'WebSite','@id':'https://hydrosealpavers.com/#website','url':'https://hydrosealpavers.com/','name':'HydroSeal'},{'@type':'WebPage','@id':url+'#webpage','url':url,'name':p['title'],'description':p['desc'],'isPartOf':{'@id':'https://hydrosealpavers.com/#website'}},{'@type':'Service','@id':url+'#service','name':p['title'].replace(' | HydroSeal',''),'serviceType':'Paver sealing, cleaning, joint-sand restoration and hardscape restoration','provider':{'@id':'https://hydrosealpavers.com/#business'},'areaServed':[{'@type':'Place','name':a} for a in p['areas']],'url':url},{'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Home','item':'https://hydrosealpavers.com/'},{'@type':'ListItem','position':2,'name':'Service Areas','item':'https://hydrosealpavers.com/service-areas'},{'@type':'ListItem','position':3,'name':p['parent'],'item':'https://hydrosealpavers.com'+p['parent_url']},{'@type':'ListItem','position':4,'name':p['name'],'item':url}]},{'@type':'FAQPage','@id':url+'#faq','mainEntity':faq}]}
