def unique_block(p):
    cards=feature_cards(p)
    layout=p['layout']
    if layout=='split':
        return f'''<section class="rg-section"><div class="rg-shell rg-rail"><aside class="rg-card rg-dark-card"><span class="rg-eyebrow" style="color:#9dd9ee;">Local inspection lens</span><h3>What changes the scope here?</h3><div class="rg-checklist"><div>Shade & dry-out</div><div>Joint depth</div><div>Drainage</div><div>Old sealer</div><div>Staining</div><div>Surface use</div></div></aside><div><span class="rg-eyebrow">Local conditions</span><h2>Four things that make {p['name']} paver work different.</h2><div class="rg-stack">{cards}</div></div></div></section>'''
    if layout=='cover':
        return f'''<section class="rg-section"><div class="rg-shell"><span class="rg-eyebrow">Property conditions</span><h2>What we evaluate before sealing in {p['name']}.</h2><p class="rg-lede">A useful restoration plan starts with exposure, moisture, joint stability and whatever coating is already on the pavers.</p><div class="rg-grid-4" style="margin-top:26px;">{cards}</div></div></section>'''
    if layout=='stat':
        return f'''<section class="rg-section"><div class="rg-shell"><span class="rg-eyebrow">Maintenance cycle</span><h2>Catch wear while the surface is still straightforward to restore.</h2><div class="rg-lifecycle"><article><b>Stage 1</b><h3>Color flattens</h3><p>Sun and daily use start changing the surface appearance.</p></article><article><b>Stage 2</b><h3>Joints drop</h3><p>Runoff and washing make low sand more noticeable.</p></article><article><b>Stage 3</b><h3>Staining builds</h3><p>Irrigation and organics increase the prep scope.</p></article><article><b>Stage 4</b><h3>Coating wears unevenly</h3><p>Compatibility becomes more important before resealing.</p></article></div><div class="rg-grid-4" style="margin-top:28px;">{cards}</div></div></section>'''
    return f'''<section class="rg-section"><div class="rg-shell rg-grid-2"><div><span class="rg-eyebrow">Local field notes</span><h2>How {p['name']} conditions change the work.</h2><p class="rg-lede">The best scope is based on what the pavers are doing now—not on a generic calendar or a one-size-fits-all coating.</p><div class="rg-btns"><a class="rg-btn rg-btn--outline" href="/paver-sealing-cost-calculator">Pricing Calculator</a><a class="rg-btn rg-btn--outline" href="/get-a-quote">Request a Quote</a></div></div><div class="rg-stack">{cards}</div></div></section>'''

def hero(p):
    if p['layout']=='cover':
        return f'''<section class="rg-hero-cover"><img src="{p['image']}" alt="{p['name']} paver sealing by HydroSeal" loading="eager" decoding="async" fetchpriority="high"/><div class="rg-shell rg-hero-cover__inner"><div class="rg-hero-panel"><span class="rg-eyebrow" style="color:#9fe5f7;">{p['eyebrow']}</span><h1>{p['h1']}</h1><p>{p['intro']}</p><div class="rg-btns"><a class="rg-btn rg-btn--blue" href="/get-a-quote">Request a Quote</a><a class="rg-btn rg-btn--white" href="tel:+19045375000">Call 904.537.5000</a></div></div></div></section>'''
    if p['layout']=='stat':
        stats=''.join(f'<div><strong>{h}</strong><span>{t}</span></div>' for h,t in p['features'])
        return f'''<section class="rg-hero-stat"><div class="rg-shell rg-hero-stat__grid"><div><span class="rg-eyebrow" style="color:#8bdcf3;">{p['eyebrow']}</span><h1>{p['h1']}</h1><p>{p['intro']}</p><div class="rg-btns"><a class="rg-btn rg-btn--blue" href="/get-a-quote">Request a Quote</a><a class="rg-btn rg-btn--white" href="tel:+19045375000">Call HydroSeal</a></div></div><div class="rg-stat-stack">{stats}</div></div></section>'''
    if p['layout']=='editorial':
        return f'''<section class="rg-hero-editorial"><div class="rg-shell rg-hero-editorial__grid"><div><span class="rg-eyebrow">{p['eyebrow']}</span><h1>{p['h1']}</h1><p class="rg-lede">{p['intro']}</p><div class="rg-btns"><a class="rg-btn rg-btn--blue" href="/get-a-quote">Request a Quote</a><a class="rg-btn rg-btn--outline" href="tel:+19045375000">Call 904.537.5000</a></div></div><div class="rg-photo"><img src="{p['image']}" alt="{p['name']} paver sealing service" loading="eager" decoding="async" fetchpriority="high"/></div></div></section>'''
    return f'''<section class="rg-hero-split"><div class="rg-shell rg-hero-split__grid"><div><span class="rg-eyebrow" style="color:#9fe5f7;">{p['eyebrow']}</span><h1>{p['h1']}</h1><p>{p['intro']}</p><div class="rg-btns"><a class="rg-btn rg-btn--blue" href="/get-a-quote">Request a Quote</a><a class="rg-btn rg-btn--white" href="tel:+19045375000">Call 904.537.5000</a></div></div><div class="rg-photo"><img src="{p['image']}" alt="{p['name']} paver sealing service" loading="eager" decoding="async" fetchpriority="high"/></div></div></section>'''

def proof():
    return '''<div class="rg-shell rg-proof"><div class="rg-proof-grid"><div><strong>Deep Cleaning</strong><span>Preparation before protection</span></div><div><strong>Joint Restoration</strong><span>ASTM C144 kiln-dried sand</span></div><div><strong>Trident Certified</strong><span>Professional sealing systems</span></div><div><strong>2-Year Warranty</strong><span>Workmanship and adhesion</span></div></div></div>'''

def faq_html(p):
    items=''.join(f'<details><summary>{q}</summary><div class="answer">{a}</div></details>' for q,a in p['faq'])
    return f'''<section class="rg-section rg-soft"><div class="rg-shell"><span class="rg-eyebrow">{p['name']} FAQ</span><h2>Questions homeowners ask before sealing.</h2><div class="rg-faq">{items}</div></div></section>'''

def related(p):
    sib=''.join(f'<li><a href="{u}">{n}</a></li>' for n,u in p['siblings'])
    return f'''<section class="rg-section"><div class="rg-shell rg-related"><div class="rg-card"><h3>Nearby Core Areas</h3><ul><li><a href="{p['parent_url']}">{p['parent']}</a></li>{sib}</ul></div><div class="rg-card"><h3>Restoration Services</h3><ul><li><a href="/paver-cleaning">Paver Cleaning</a></li><li><a href="/paver-repair">Paver Repair</a></li><li><a href="/paver-resealing">Paver Resealing</a></li><li><a href="/paver-sealing/sand-options">Joint Sand Options</a></li></ul></div><div class="rg-card"><h3>Planning Guides</h3><ul><li><a href="/learning-center/sealing/what-should-professional-paver-sealing-include">What Professional Sealing Includes</a></li><li><a href="/learning-center/problems/why-is-sand-coming-out-of-my-pavers">Why Joint Sand Comes Out</a></li><li><a href="/paver-sealing-cost-calculator">Pricing Calculator</a></li></ul></div></div></section>'''

def page(p):
    url='https://hydrosealpavers.com/'+p['path'].replace('.html','')
    meta=f'''<!doctype html><html lang="en"><head>{GTAG}<meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><link rel="icon" href="/assets/favicons/favicon.ico" sizes="any"/><meta name="theme-color" content="#0F6EA8"/><title>{p['title']}</title><meta name="description" content="{p['desc']}"/><meta name="robots" content="index,follow,max-image-preview:large"/><link rel="canonical" href="{url}"/><meta property="og:type" content="website"/><meta property="og:site_name" content="HydroSeal"/><meta property="og:title" content="{p['title']}"/><meta property="og:description" content="{p['desc']}"/><meta property="og:url" content="{url}"/><meta property="og:image" content="https://hydrosealpavers.com{p['image']}"/><meta name="twitter:card" content="summary_large_image"/><meta name="twitter:title" content="{p['title']}"/><meta name="twitter:description" content="{p['desc']}"/><meta name="twitter:image" content="https://hydrosealpavers.com{p['image']}"/>{CSS}<script type="application/ld+json">{schema(p,url)}</script></head><body><div data-include="/partials/header.html"></div>'''
    body=f'''<main id="page" data-page class="rg-page rg-{p['slug']}">{hero(p)}{proof()}{unique_block(p)}{SERVICES}{PROCESS}<section class="rg-section"><div class="rg-shell"><div class="elfsight-app-bfab489f-7fca-4f05-ba5a-d92616b76b26" data-elfsight-app-lazy></div></div></section>{faq_html(p)}{related(p)}<section class="rg-trust"><div class="rg-shell rg-trust-grid"><div>Licensed & Insured</div><div>Trident Master Certified</div><div>ASTM C144 Joint Sand</div><div>2-Year Workmanship Warranty</div></div></section><section class="rg-final"><div class="rg-shell rg-final-grid"><div><span class="rg-eyebrow" style="color:#8bdcf3;">{p['name']} estimates</span><h2>Find out what your pavers actually need.</h2><p>Send the property address and photos of the driveway, pool deck, patio or walkway. HydroSeal can review the likely cleaning, sanding, repair and sealing scope.</p></div><div class="rg-btns"><a class="rg-btn rg-btn--blue" href="/get-a-quote">Request a Quote</a><a class="rg-btn rg-btn--white" href="tel:+19045375000">Call HydroSeal</a></div></div></section></main>'''
    foot='''<div data-include="/partials/footer.html"></div><script src="/assets/js/include.js" defer></script><script src="/assets/js/router.js" defer></script><script src="/assets/js/nav.js" defer></script><script src="/assets/js/analytics.js" defer></script><script defer src="/assets/js/third-party-loader.js"></script></body></html>'''
    return meta+body+foot

for p in PAGES:
    Path(p['path']).write_text(page(p))
print(f'Rebuilt {len(PAGES)} Clay and St. Johns County child location pages.')
